using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "PurifyCorruptWithMultiplierPreviewDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/PreviewDescription/Any/PurifyCorruptWithMultiplierPreviewDescription", order = 0)]
public class PurifyCorruptWithMultiplierPreviewDescription : PreviewDescription
{
	public override int GetPreviewAmount(string amountModified, BattleAction battleAction)
	{
		PurifyCorruptWithMultiplierActions obj = battleAction as PurifyCorruptWithMultiplierActions;
		int finalAmountWithoutEquation = GetFinalAmountWithoutEquation(amountModified);
		return obj.PurifyAmount(finalAmountWithoutEquation, checkConditionToBeCastedOrPreview: true);
	}

	public override int GetTimesPreviewAmount(string amountModified, BattleAction battleAction)
	{
		return (battleAction as PurifyCorruptWithMultiplierActions).PurifyCounter(checkConditionToBeCastedOrPreview: true);
	}
}
